  try {
    var q = new URLSearchParams(location.search), got = {}, any = false;
    KEYS.forEach(function (k) { var v = q.get('utm_' + k); if (v) { got[k] = v.slice(0, 200); any = true; } });
    if (any) { got.ts = Date.now(); localStorage.setItem('pfUTM', JSON.stringify(got)); }
  } catch (e) {}
